import{_ as n,o as e,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Hukum Perlindungan Konsumen","description":"","frontmatter":{},"headers":[],"relativePath":"id/42-消费者保护法.md","filePath":"id/42-消费者保护法.md","lastUpdated":1789183869000}'),r={name:"id/42-消费者保护法.md"};function u(s,a,d,k,m,g){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="hukum-perlindungan-konsumen" tabindex="-1">Hukum Perlindungan Konsumen <a class="header-anchor" href="#hukum-perlindungan-konsumen" aria-label="Permalink to &quot;Hukum Perlindungan Konsumen&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>42</td></tr><tr><td>Modul</td><td>Sistem Hukum dan Kerangka Tata Kelola</td></tr><tr><td>Kata kunci utama</td><td>Hak Konsumen, Transaksi Adil, Anti-penipuan, Tanggung Jawab Produk, Pasar Simbiosis</td></tr></tbody></table><h2 id="i-tujuan-legislasi-dan-ruang-lingkup-penerapan" tabindex="-1">I. Tujuan Legislasi dan Ruang Lingkup Penerapan <a class="header-anchor" href="#i-tujuan-legislasi-dan-ruang-lingkup-penerapan" aria-label="Permalink to &quot;I. Tujuan Legislasi dan Ruang Lingkup Penerapan&quot;">​</a></h2><p>《Hukum Perlindungan Konsumen》 adalah salah satu hukum inti dalam sistem hukum peradaban simbiosis jangkar, dan bersama dengan 《Hukum Kerja Simbiosis》 merupakan dua pilar kehidupan ekonomi. Hukum ini bertujuan untuk melindungi hak dan kepentingan sah semua konsumen di dalam Hengyuanzhou, mengatur perilaku transaksi pasar, menjaga tatanan pasar yang adil, jujur, dan simbiosis, serta mencegah pelanggaran hak dan kepentingan semua makhluk oleh perilaku komersial predator.</p><p>Hukum ini berlaku untuk semua konsumen di dalam Hengyuanzhou yang membeli, menggunakan barang, atau menerima jasa untuk memenuhi kebutuhan hidup pribadi atau keluarga, serta operator yang menyediakan barang atau jasa kepada konsumen. Transaksi antar bidang juga tunduk pada hukum ini, tetapi aturan pelaksanaan rinci dapat disusun sesuai dengan perbedaan bidang.</p><h2 id="ii-hak-dasar-konsumen" tabindex="-1">II. Hak Dasar Konsumen <a class="header-anchor" href="#ii-hak-dasar-konsumen" aria-label="Permalink to &quot;II. Hak Dasar Konsumen&quot;">​</a></h2><p>Hukum ini menetapkan bahwa konsumen menikmati sembilan hak dasar berikut:</p><table tabindex="0"><thead><tr><th>Hak</th><th>Isi</th></tr></thead><tbody><tr><td>Hak Jaminan Keamanan</td><td>Konsumen saat membeli, menggunakan barang, dan menerima jasa menikmati hak agar keamanan pribadi dan harta benda tidak dirugikan</td></tr><tr><td>Hak Mengetahui Kebenaran</td><td>Konsumen berhak mengetahui situasi sebenarnya dari barang yang dibeli atau digunakan atau jasa yang diterima, termasuk komposisi, khasiat, risiko, dll.</td></tr><tr><td>Hak Pilihan Mandiri</td><td>Konsumen berhak memilih secara mandiri barang atau jasa, berhak melakukan perbandingan, identifikasi, dan pemilihan, serta menolak transaksi paksa</td></tr><tr><td>Hak Transaksi Adil</td><td>Konsumen berhak mendapatkan kondisi transaksi yang adil seperti jaminan kualitas, harga wajar, pengukuran yang benar, dll.</td></tr><tr><td>Hak Ganti Rugi Sesuai Hukum</td><td>Konsumen yang menderita kerugian pribadi atau harta benda karena membeli, menggunakan barang, atau menerima jasa menikmati hak untuk mendapatkan ganti rugi sesuai hukum</td></tr><tr><td>Hak Berorganisasi untuk Membela Hak</td><td>Konsumen berhak mendirikan atau bergabung dengan organisasi konsumen sesuai hukum, untuk membela hak dan kepentingan sahnya sendiri</td></tr><tr><td>Hak Mendapatkan Pengetahuan</td><td>Konsumen berhak mendapatkan pengetahuan dan informasi terkait konsumsi dan perlindungan hak serta kepentingan konsumen</td></tr><tr><td>Hak Dihormati</td><td>Konsumen saat membeli, menggunakan barang, dan menerima jasa menikmati hak agar martabat pribadi dan adat istiadat etnis dihormati</td></tr><tr><td>Hak Pengawasan</td><td>Konsumen berhak mengawasi barang dan jasa serta pekerjaan perlindungan hak dan kepentingan konsumen, serta memberikan kritik dan saran</td></tr></tbody></table><h2 id="iii-kewajiban-operator" tabindex="-1">III. Kewajiban Operator <a class="header-anchor" href="#iii-kewajiban-operator" aria-label="Permalink to &quot;III. Kewajiban Operator&quot;">​</a></h2><p>Operator saat menyediakan barang atau jasa kepada konsumen harus memenuhi kewajiban berikut:</p><ol><li><strong>Kewajiban Beroperasi Sesuai Hukum</strong>: Operator harus mematuhi Konstitusi dan hukum, dan melakukan kegiatan usaha dalam lingkup usaha yang disetujui.</li><li><strong>Kewajiban Jaminan Keamanan</strong>: Operator harus memastikan barang atau jasa yang disediakan memenuhi persyaratan jaminan keamanan pribadi dan harta benda, dan harus memberikan penjelasan sebenarnya serta peringatan yang jelas untuk barang dan jasa yang dapat membahayakan keamanan.</li><li><strong>Kewajiban Informasi Sebenar</strong>: Operator harus memberikan informasi sebenarnya tentang barang atau jasa kepada konsumen, dan tidak boleh melakukan promosi palsu atau menyesatkan. Barang dan jasa kategori kultivasi harus menandai batas khasiat dan risiko potensial secara sebenarnya.</li><li><strong>Kewajiban Jaminan Kualitas</strong>: Operator harus memastikan bahwa dalam kondisi penggunaan normal barang atau penerimaan jasa, barang atau jasa yang disediakan memiliki kualitas, kinerja, kegunaan, dan masa berlaku yang seharusnya dimiliki.</li><li><strong>Kewajiban Transaksi Adil</strong>: Operator tidak boleh melalui ketentuan baku, pemberitahuan, pernyataan, pengumuman toko, dll. membuat ketentuan yang tidak adil dan tidak wajar bagi konsumen, seperti mengecualikan atau membatasi hak konsumen, mengurangi atau membebaskan tanggung jawab operator, memperberat tanggung jawab konsumen, dll.</li><li><strong>Kewajiban Layanan Purna Jual</strong>: Operator harus sesuai dengan ketentuan negara atau perjanjian dengan konsumen, menanggung tanggung jawab perbaikan, penggantian, pengembalian, dan layanan purna jual lainnya.</li><li><strong>Kewajiban Perlindungan Privasi</strong>: Operator harus melindungi informasi pribadi dan data kesadaran konsumen, dan tidak boleh mengumpulkan, menggunakan, atau membocorkan tanpa persetujuan konsumen.</li></ol><h2 id="iv-penyelesaian-sengketa-dan-tanggung-jawab-hukum" tabindex="-1">IV. Penyelesaian Sengketa dan Tanggung Jawab Hukum <a class="header-anchor" href="#iv-penyelesaian-sengketa-dan-tanggung-jawab-hukum" aria-label="Permalink to &quot;IV. Penyelesaian Sengketa dan Tanggung Jawab Hukum&quot;">​</a></h2><p>Ketika terjadi sengketa hak dan kepentingan konsumen antara konsumen dan operator, dapat diselesaikan melalui cara berikut:</p><ul><li>Negosiasi dan rekonsiliasi dengan operator</li><li>Meminta mediasi kepada organisasi konsumen</li><li>Mengajukan keluhan kepada departemen administratif terkait</li><li>Mengajukan arbitrase kepada lembaga arbitrase sesuai perjanjian arbitrase yang dicapai dengan operator</li><li>Menggugat ke Pengadilan Simbiosis</li></ul><p>Operator yang melanggar ketentuan hukum ini dan melanggar hak dan kepentingan sah konsumen harus menanggung tanggung jawab berikut:</p><table tabindex="0"><thead><tr><th>Perilaku Ilegal</th><th>Tanggung Jawab Hukum</th></tr></thead><tbody><tr><td>Menyediakan barang atau jasa cacat yang menyebabkan kerugian</td><td>Menanggung tanggung jawab ganti rugi, termasuk biaya pengobatan, ganti rugi kehilangan pekerjaan, ganti rugi cacat, dll.</td></tr><tr><td>Perilaku penipuan</td><td>Menambah ganti rugi sesuai permintaan konsumen, jumlahnya adalah tiga kali harga barang yang dibeli konsumen atau biaya jasa yang diterima</td></tr><tr><td>Promosi palsu</td><td>Diperintahkan menghentikan perilaku ilegal, menghilangkan pengaruh, didenda</td></tr><tr><td>Transaksi paksa</td><td>Diperintahkan memperbaiki, mengembalikan biaya tidak wajar, didenda</td></tr><tr><td>Melanggar privasi konsumen</td><td>Menanggung ganti rugi kerusakan moral, dalam kasus parah dituntut tanggung jawab pidana</td></tr></tbody></table><h2 id="v-organisasi-konsumen-dan-pengawasan-sosial" tabindex="-1">V. Organisasi Konsumen dan Pengawasan Sosial <a class="header-anchor" href="#v-organisasi-konsumen-dan-pengawasan-sosial" aria-label="Permalink to &quot;V. Organisasi Konsumen dan Pengawasan Sosial&quot;">​</a></h2><p>Negara mendorong dan mendukung semua organisasi dan individu untuk melakukan pengawasan sosial terhadap perilaku yang merugikan hak dan kepentingan sah konsumen. Asosiasi Konsumen adalah organisasi sosial yang didirikan sesuai hukum untuk melakukan pengawasan sosial terhadap barang dan jasa serta melindungi hak dan kepentingan sah konsumen, dan menjalankan fungsi berikut:</p><ol><li>Memberikan informasi konsumsi dan layanan konsultasi kepada konsumen</li><li>Berpartisipasi dalam pengawasan dan pemeriksaan barang dan jasa oleh departemen administratif terkait</li><li>Menyampaikan, menanyakan, dan memberikan saran kepada departemen administratif terkait mengenai masalah hak dan kepentingan sah konsumen</li><li>Menerima keluhan konsumen, dan melakukan penyelidikan serta mediasi terhadap masalah yang dikeluhkan</li><li>Mendukung konsumen yang dirugikan untuk menggugat terhadap perilaku yang merugikan hak dan kepentingan sah konsumen</li></ol><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>《Hukum Perlindungan Konsumen》 adalah penjaga tatanan pasar peradaban simbiosis jangkar. Dengan memberikan hak yang memadai kepada konsumen, membatasi perilaku operator, dan membangun mekanisme penyelesaian sengketa yang beragam, ia memastikan transaksi pasar berjalan di jalur yang adil, jujur, dan simbiosis, serta mencegah sektor komersial menjadi lahan subur baru bagi perilaku predator.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen terkait&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Prinsip Umum Konstitusi Simbiosis)</li><li>41-共生劳动法 (Hukum Kerja Simbiosis)</li><li>47-反垄断法 (Hukum Anti-Monopoli)</li><li>36-社会结构与阶层流动 (Struktur Sosial dan Mobilitas Kelas)</li></ul>',23)])])}const p=n(r,[["render",u]]);export{o as __pageData,p as default};
